Here is the refactored version using **`async/await`**:

### 1. If your database driver already supports Promises
*(e.g., `mysql2/promise`, `pg`, or modern ORMs/query builders)*

```javascript
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);

  if (!rows.length) {
    throw new Error('Not found');
  }

  return rows[0];
}
```

---

### 2. If your database driver is callback-only
*(e.g., the legacy `mysql` package, where `db.query` does not return a Promise)*

You can wrap the query in a `Promise`:

```javascript
async function getUser(id) {
  return new Promise((resolve, reject) => {
    db.query('SELECT * FROM users WHERE id = ?', [id], (err, rows) => {
      if (err) return reject(err);
      if (!rows.length) return reject(new Error('Not found'));
      resolve(rows[0]);
    });
  });
}
```

---

### How to use it:

```javascript
try {
  const user = await getUser(1);
  console.log(user);
} catch (err) {
  console.error(err.message);
}
```

