Here is a complete, production-ready React Error Boundary component in **TypeScript** (compatible with JavaScript by removing the type annotations).

Error Boundaries in React **must be class components** because hooks do not currently support `componentDidCatch` or `getDerivedStateFromError`.

---

### `ErrorBoundary.tsx`

```tsx
import React, { Component, ReactNode, ErrorInfo } from 'react';

interface ErrorBoundaryProps {
  children: ReactNode;
  /** Optional custom fallback UI. Can be a ReactNode or a render function. */
  fallback?: ReactNode | ((props: { error: Error; resetErrorBoundary: () => void }) => ReactNode);
  /** Optional callback triggered when an error is caught */
  onError?: (error: Error, errorInfo: ErrorInfo) => void;
  /** Optional callback triggered when the user resets the boundary */
  onReset?: () => void;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
}

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
    };
  }

  // 1. Update state so the next render shows the fallback UI
  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return {
      hasError: true,
      error,
    };
  }

  // 2. Log error details to the console or an external logging service (e.g., Sentry)
  componentDidCatch(error: Error, errorInfo: ErrorInfo): void {
    console.error('ErrorBoundary caught an error:', error, errorInfo);

    // Call external logging handler if provided
    if (this.props.onError) {
      this.props.onError(error, errorInfo);
    }
  }

  // 3. Reset error state to retry rendering children
  resetErrorBoundary = (): void => {
    if (this.props.onReset) {
      this.props.onReset();
    }
    this.setState({
      hasError: false,
      error: null,
    });
  };

  render(): ReactNode {
    const { hasError, error } = this.state;
    const { fallback, children } = this.props;

    if (hasError && error) {
      // If a custom fallback render function is provided
      if (typeof fallback === 'function') {
        return fallback({ error, resetErrorBoundary: this.resetErrorBoundary });
      }

      // If a custom static fallback ReactNode is provided
      if (fallback) {
        return fallback;
      }

      // Default Fallback UI
      return (
        <div
          role="alert"
          style={{
            padding: '24px',
            margin: '16px',
            border: '1px solid #ff4d4f',
            borderRadius: '8px',
            backgroundColor: '#fff1f0',
            color: '#434343',
            fontFamily: 'sans-serif',
          }}
        >
          <h2 style={{ margin: '0 0 12px 0', color: '#cf1322' }}>
            Something went wrong.
          </h2>
          <details style={{ whiteSpace: 'pre-wrap', marginBottom: '16px' }}>
            <summary style={{ cursor: 'pointer', fontWeight: 'bold' }}>
              View error details
            </summary>
            <p style={{ marginTop: '8px', color: '#a8071a' }}>
              {error.toString()}
            </p>
          </details>
          <button
            onClick={this.resetErrorBoundary}
            style={{
              padding: '8px 16px',
              backgroundColor: '#1890ff',
              color: '#fff',
              border: 'none',
              borderRadius: '4px',
              cursor: 'pointer',
              fontWeight: 'bold',
            }}
          >
            Try Again
          </button>
        </div>
      );
    }

    return children;
  }
}
```

---

### Usage Example

```tsx
import React, { useState } from 'react';
import { ErrorBoundary } from './ErrorBoundary';

// A component that can intentionally throw an error
const BuggyComponent = () => {
  const [shouldCrash, setShouldCrash] = useState(false);

  if (shouldCrash) {
    throw new Error('💥 An intentional render error occurred!');
  }

  return (
    <div style={{ padding: '16px', border: '1px solid #ccc' }}>
      <h3>Child Component</h3>
      <button onClick={() => setShouldCrash(true)}>Trigger Error</button>
    </div>
  );
};

export default function App() {
  return (
    <div>
      <h1>Error Boundary Demo</h1>

      {/* 1. Default UI fallback */}
      <ErrorBoundary
        onError={(error, info) => {
          // Send to logging service (e.g., Datadog, Sentry)
          // logErrorToService(error, info);
        }}
      >
        <BuggyComponent />
      </ErrorBoundary>

      {/* 2. Custom UI fallback via function */}
      <ErrorBoundary
        fallback={({ error, resetErrorBoundary }) => (
          <div style={{ padding: '20px', background: '#ffebee' }}>
            <h3>Custom Fallback</h3>
            <p>{error.message}</p>
            <button onClick={resetErrorBoundary}>Retry</button>
          </div>
        )}
      >
        <BuggyComponent />
      </ErrorBoundary>
    </div>
  );
}
```

### Key Features:
1. **`getDerivedStateFromError`**: Catches errors in the rendering lifecycle and switches the UI to the fallback state without crashing the whole application.
2. **`componentDidCatch`**: Logs the error and the component stack trace (`ErrorInfo`).
3. **`resetErrorBoundary`**: Clears the error state to allow re-rendering when the user clicks the **Try Again** button.
4. **Flexible Fallback**: Supports the built-in UI, a static custom React element, or a render-prop callback receiving `error` and `resetErrorBoundary`.
